"use client";

/* eslint-disable @next/next/no-img-element -- Embedded portraits keep the exported component independent of Next.js image configuration. */

import { useId, useRef, useState, type KeyboardEvent } from "react";

export interface PortraitGalleryItem {
  /** Stable, unique identifier for the portrait. */
  id: string;
  name: string;
  image: string;
  /** CSS object-position, for example "50% 35%". */
  imagePosition?: string;
}

export interface PortraitGalleryProps {
  items?: readonly PortraitGalleryItem[];
  /** Leave unset for the reference's equal-width resting state. */
  initialIndex?: number | null;
  /** Called on click, tap, Enter, or Space; hovering only previews a portrait. */
  onSelect?: (item: PortraitGalleryItem, index: number) => void;
  ariaLabel?: string;
  className?: string;
}

function initialPortraitId(
  items: readonly PortraitGalleryItem[],
  index: number | null | undefined,
): string | null {
  if (index == null || !Number.isFinite(index) || items.length === 0) return null;
  return items[Math.max(0, Math.min(items.length - 1, Math.floor(index)))].id;
}

function galleryColumns(count: number, activeIndex: number): string {
  return Array.from({ length: count }, (_, index) =>
    index === activeIndex ? "3fr" : "1fr",
  ).join(" ");
}

function PortraitArtwork({ item }: { item: PortraitGalleryItem }) {
  return (
    <>
      <img
        className="pg-image"
        src={item.image}
        alt=""
        draggable={false}
        decoding="async"
        loading="lazy"
        style={{ objectPosition: item.imagePosition ?? "center" }}
      />
      <span className="pg-name" aria-hidden="true">{item.name}</span>
    </>
  );
}

/** A staggered portrait strip with hover previews and persistent touch selection. */
export function PortraitGallery({
  items = DEFAULT_PORTRAITS,
  initialIndex = null,
  onSelect,
  ariaLabel = "Character portrait gallery",
  className = "",
}: PortraitGalleryProps) {
  const [selectedId, setSelectedId] = useState<string | null>(() =>
    initialPortraitId(items, initialIndex),
  );
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [focusedId, setFocusedId] = useState<string | null>(null);
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const instructionsId = useId();

  // Ignore stale IDs when a parent replaces or reorders the portrait collection.
  const activeId = [hoveredId, focusedId, selectedId].find((id) =>
    id !== null && items.some((item) => item.id === id),
  );
  const activeIndex = items.findIndex((item) => item.id === activeId);
  const focusedIndex = items.findIndex((item) => item.id === focusedId);
  const tabIndex = focusedIndex >= 0 ? focusedIndex : Math.max(0, activeIndex);

  function navigate(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let nextIndex: number;
    switch (event.key) {
      case "ArrowRight": nextIndex = (index + 1) % items.length; break;
      case "ArrowLeft": nextIndex = (index - 1 + items.length) % items.length; break;
      case "Home": nextIndex = 0; break;
      case "End": nextIndex = items.length - 1; break;
      default: return;
    }
    event.preventDefault();
    setHoveredId(null);
    buttonRefs.current[nextIndex]?.focus();
  }

  return (
    <section className={`portrait-gallery w-full bg-black text-white ${className}`} aria-label={ariaLabel}>
      <style>{PORTRAIT_GALLERY_STYLES}</style>
      <p id={instructionsId} className="pg-sr-only">
        Hover or focus a portrait to expand it. Use the left and right arrow keys,
        Home, or End to move between portraits. Click, tap, Enter, or Space to
        keep a portrait selected.
      </p>
      <div className="pg-stage">
        {items.length > 0 ? (
          <div
            className="pg-grid"
            role="group"
            aria-label="Portraits"
            data-expanded={activeIndex >= 0}
            style={{ gridTemplateColumns: galleryColumns(items.length, activeIndex) }}
            onPointerLeave={() => setHoveredId(null)}
            onBlur={(event) => {
              if (!event.currentTarget.contains(event.relatedTarget)) setFocusedId(null);
            }}
          >
            {items.map((item, index) => (
              <button
                key={item.id}
                ref={(element) => { buttonRefs.current[index] = element; }}
                className="pg-portrait"
                type="button"
                data-active={index === activeIndex}
                aria-label={`Select ${item.name}`}
                aria-describedby={instructionsId}
                aria-pressed={selectedId === item.id}
                tabIndex={index === tabIndex ? 0 : -1}
                onPointerEnter={(event) => {
                  if (event.pointerType !== "touch") setHoveredId(item.id);
                }}
                onFocus={() => { setHoveredId(null); setFocusedId(item.id); }}
                onKeyDown={(event) => navigate(event, index)}
                onClick={() => { setSelectedId(item.id); onSelect?.(item, index); }}
              >
                <PortraitArtwork item={item} />
              </button>
            ))}
          </div>
        ) : (
          <p className="pg-empty">No portraits to display.</p>
        )}
      </div>
    </section>
  );
}

/** No handlers or timers: the homepage controls these automatically cycling frames. */
export function PortraitGalleryThumbnail({
  className = "",
  previewStep = 0,
}: { className?: string; previewStep?: number }) {
  const step = Number.isFinite(previewStep) ? Math.max(0, Math.floor(previewStep)) : 0;
  const activeIndex = DEFAULT_PORTRAITS.length - 1 - (step % DEFAULT_PORTRAITS.length);

  return (
    <div className={`portrait-gallery portrait-gallery--thumbnail w-full bg-black ${className}`} aria-hidden="true">
      <style>{PORTRAIT_GALLERY_STYLES}</style>
      <div className="pg-stage">
        <div
          className="pg-grid"
          data-expanded="true"
          style={{ gridTemplateColumns: galleryColumns(DEFAULT_PORTRAITS.length, activeIndex) }}
        >
          {DEFAULT_PORTRAITS.map((item, index) => (
            <div className="pg-portrait" key={item.id} data-active={index === activeIndex}>
              <PortraitArtwork item={item} />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default PortraitGallery;

const PORTRAIT_GALLERY_STYLES = `
  @font-face {
    font-family: "PortraitGalleryFigtree";
    src: url("data:font/ttf;base64,") format("truetype");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
  }
  .portrait-gallery {
    container-type: inline-size;
    isolation: isolate;
    width: 100%;
    background: #000;
    color: #fff;
    font-family: "PortraitGalleryFigtree", Arial, sans-serif;
  }
  .portrait-gallery * { box-sizing: border-box; }
  .portrait-gallery .pg-stage {
    display: grid;
    place-items: center;
    padding: clamp(40px, 6.5cqw, 64px) clamp(20px, 3.5cqw, 30px);
  }
  .portrait-gallery .pg-grid {
    --pg-gap: clamp(6px, 1.86cqw, 16px);
    --pg-offset: clamp(8px, 1.86cqw, 16px);
    display: grid;
    gap: var(--pg-gap);
    width: 100%;
    max-width: 800px;
    aspect-ratio: 8 / 5;
    min-height: 220px;
    transition: grid-template-columns 400ms ease;
  }
  .portrait-gallery .pg-portrait {
    position: relative;
    display: block;
    min-width: 0;
    min-height: 0;
    overflow: hidden;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: #000;
    color: #fff;
    font: inherit;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition: filter 400ms ease;
  }
  .portrait-gallery .pg-portrait:nth-child(odd) { transform: translateY(calc(-1 * var(--pg-offset))); }
  .portrait-gallery .pg-portrait:nth-child(even) { transform: translateY(var(--pg-offset)); }
  .portrait-gallery .pg-grid[data-expanded="true"] .pg-portrait:not([data-active="true"]) {
    filter: grayscale(1) opacity(.24);
  }
  .portrait-gallery .pg-portrait:focus-visible { outline: 2px solid #fff; outline-offset: 4px; }
  .portrait-gallery .pg-image {
    position: absolute;
    inset: 0;
    display: block;
    width: 100%;
    height: 100%;
    max-width: none;
    object-fit: cover;
    pointer-events: none;
    user-select: none;
  }
  .portrait-gallery .pg-name {
    position: absolute;
    bottom: clamp(12px, 2.33cqw, 20px);
    left: 50%;
    max-width: calc(100% - 8px);
    overflow: hidden;
    padding: clamp(7px, 1.16cqw, 10px) clamp(7px, 1.16cqw, 10px) clamp(7px, 1.16cqw, 10px) clamp(9px, 1.63cqw, 14px);
    background: #000;
    color: #fff;
    font-size: clamp(10px, 1.86cqw, 16px);
    font-weight: 400;
    line-height: 1.2;
    letter-spacing: clamp(2px, .47cqw, 4px);
    text-transform: uppercase;
    text-overflow: ellipsis;
    white-space: nowrap;
    opacity: 0;
    transform: translate(-50%, 60px);
    transition: opacity 400ms ease, transform 400ms ease;
    pointer-events: none;
  }
  .portrait-gallery .pg-portrait[data-active="true"] .pg-name {
    opacity: 1;
    transform: translate(-50%, 0);
    transition-delay: 400ms;
  }
  .portrait-gallery .pg-sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    padding: 0;
    margin: -1px;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }
  .portrait-gallery .pg-empty { margin: 0; padding: 80px 0; color: #999; font: 14px Arial, sans-serif; }
  .portrait-gallery--thumbnail .pg-stage { height: 100%; padding: 36px max(20px, 7cqw); }
  .portrait-gallery--thumbnail .pg-grid { min-height: 0; }
  .portrait-gallery--thumbnail .pg-portrait { cursor: default; }
  @media (prefers-reduced-motion: reduce) {
    .portrait-gallery .pg-grid,
    .portrait-gallery .pg-portrait,
    .portrait-gallery .pg-name { transition: none; }
  }
`;

// Portraits from the supplied reference's Character Showcase Gallery:
// https://codepen.io/pleasedonotdisturb/pen/poqrZLZ
// Embedded originals keep this component usable without remote image hosting.
const DEFAULT_PORTRAITS: readonly PortraitGalleryItem[] = [
  { id: "renji", name: "Renji", image: "data:image/jpeg;base64," },
  { id: "sora", name: "Sora", image: "data:image/jpeg;base64," },
  { id: "kaito", name: "Kaito", image: "data:image/jpeg;base64," },
  { id: "tsuki", name: "Tsuki", image: "data:image/jpeg;base64," },
  { id: "mitsui", name: "Mitsui", image: "data:image/jpeg;base64," },
];

